package com.bank.flow;

import java.math.BigDecimal;

public class TransferService {
    // A small, pure method. Calling it millions of times is what lets the
    // JVM profiler mark it "hot" and JIT-compile it into native machine code.
    public void transfer(Account from, Account to, BigDecimal amount) {
        from.debit(amount);
        to.credit(amount);
    }
}
