package com.bank.flow;

import java.math.BigDecimal;
import java.util.logging.*;

public class CompilationFlowDemo {
    private static final Logger log = Logger.getLogger(CompilationFlowDemo.class.getName());

    // A static block runs during class initialization — the step AFTER loading
    // and verification, BEFORE main. Seeing this line proves initialization ran.
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setLevel(Level.ALL);
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
        log.fine("Static initializer ran: class initialization complete");
    }

    public static void main(String[] args) {
        // Prove which class loader loaded us — application loader for our classes.
        log.info(() -> "Loaded by: " + CompilationFlowDemo.class.getClassLoader());

        Account rajesh = new Account("SAV2001", "Rajesh Kumar", new BigDecimal("1000000"));
        Account priya  = new Account("CUR3001", "Priya Sharma", new BigDecimal("250000"));
        TransferService service = new TransferService();

        // 1) One clear transfer to show ordinary interpreted execution.
        BigDecimal rentAmount = new BigDecimal("50000");
        service.transfer(rajesh, priya, rentAmount);
        log.info(() -> "After single transfer -> Rajesh=" + rajesh.getBalance()
                + " Priya=" + priya.getBalance());

        // 2) Warm up the JIT: transfer 1 rupee back and forth many times.
        Account a = new Account("SAV2001", "Rajesh Kumar", new BigDecimal("1000000"));
        Account b = new Account("CUR3001", "Priya Sharma", new BigDecimal("250000"));
        BigDecimal one = BigDecimal.ONE;
        long totalTransfers = 0;

        long coldStart = System.nanoTime();
        for (int i = 0; i < 100_000; i++) { service.transfer(a, b, one); service.transfer(b, a, one); totalTransfers += 2; }
        long coldNs = System.nanoTime() - coldStart;
        log.info(() -> "Cold batch (interpreter + early JIT) took " + (coldNs / 1_000_000) + " ms");

        long hotStart = System.nanoTime();
        for (int i = 0; i < 100_000; i++) { service.transfer(a, b, one); service.transfer(b, a, one); totalTransfers += 2; }
        long hotNs = System.nanoTime() - hotStart;
        log.info(() -> "Hot batch (JIT-compiled to native) took " + (hotNs / 1_000_000) + " ms");

        final long done = totalTransfers;
        log.info(() -> "Total transfers executed: " + done);
    }
}
